sys_script_include.script:
var TrainingRefQual = Class.create();
TrainingRefQual.prototype = {
    initialize: function () {},

    getInstructorsQuery: function (groupSysId, groupName) {
        var resolvedGroupSysId = '';


        if (groupSysId) {
            resolvedGroupSysId = groupSysId;
        } else {

            var nameToFind = groupName;
            if (!nameToFind) {
                nameToFind = 'Training Instructors';
            }
            var grp = new GlideRecord('sys_user_group');
            grp.addQuery('name', nameToFind);
            grp.setLimit(1);
            grp.query();
            if (grp.next()) {
                resolvedGroupSysId = grp.getUniqueValue();
            }
        }

        if (!resolvedGroupSysId) {
            return 'sys_id=NULL';
        }

        var ids = [];
        var grm = new GlideRecord('sys_user_grmember');
        grm.addQuery('group', resolvedGroupSysId);
        grm.query();
        while (grm.next()) {
            ids.push(grm.user.toString());
        }

        if (ids.length === 0) {
            return 'sys_id=NULL';
        }

        return 'active=true^sys_idIN' + ids.join(',');
    },

    type: 'TrainingRefQual'
};
